        }
        self.taken = saved;
    }

    fn stmt(&mut self, s: &Stmt, stack: &mut Vec<Scope>) {
        match s {
            Stmt::Let(l) if !l.params.is_empty() => self.function(&l.params, &l.value),
            Stmt::Let(l) => self.expr(&l.value, stack),
            Stmt::Assign(_, _, e, _) | Stmt::Expr(e) => self.expr(e, stack),
        }
    }

