}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum BinOp {
    Add,
    Sub,
    Mul,
    Div,
    FloorDiv,
    Mod,
    Pow,
    And,
    Or,
    PipeRight,
    PipeLeft,
    ComposeRight,
    ComposeLeft,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum CmpOp {
    Eq,
    Ne,
    Lt,
    Le,
    Gt,
    Ge,
}

impl BinOp {
    pub fn text(self) -> &'static str {
        match self {
            BinOp::Add => "+",
            BinOp::Sub => "-",
            BinOp::Mul => "*",
            BinOp::Div => "/",
            BinOp::FloorDiv => "//",
            BinOp::Mod => "%",
            BinOp::Pow => "**",
            BinOp::And => "and",
            BinOp::Or => "or",
            BinOp::PipeRight => "|>",
            BinOp::PipeLeft => "<|",
            BinOp::ComposeRight => ">>",
            BinOp::ComposeLeft => "<<",
        }
    }
}

impl CmpOp {
    pub fn text(self) -> &'static str {
        match self {
            CmpOp::Eq => "==",
            CmpOp::Ne => "!=",
            CmpOp::Lt => "<",
            CmpOp::Le => "<=",
            CmpOp::Gt => ">",
            CmpOp::Ge => ">=",
        }
    }
}

/// An operator section `(op)`.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum SectionOp {
    Bin(BinOp),
    Cmp(CmpOp),
}

impl SectionOp {
    pub fn text(self) -> &'static str {
        match self {
            SectionOp::Bin(b) => b.text(),
            SectionOp::Cmp(c) => c.text(),
        }
    }
}

#[derive(Clone, Debug, PartialEq)]
pub enum FPart {
    Text(String),
    Expr(Expr),
}

/// A unit-of-measure expression: a product of powers of named units (or
