    Chain(Box<Expr>, Vec<(CmpOp, Expr)>),
    Neg(Box<Expr>),
    Not(Box<Expr>),
    Try(Box<Expr>),
    If(Box<Expr>, Box<Expr>, Box<Expr>),
    Match(Box<Expr>, Vec<Arm>),
    Lambda(Vec<Pat>, Box<Expr>),
    Block(Vec<Stmt>),
    Tuple(Vec<Expr>),
    List(Vec<Expr>),
