pub fn session_source(entries: &[String], input: &str) -> String {
    let mut s = String::from("\n");
    for e in entries {
        s.push_str(e);
        s.push('\n');
    }
    s.push_str(input);
    s
}

fn is_unit(t: &Ty) -> bool {
    matches!(t, Ty::Con(n, _) if n == "unit")
