fn python_cmd() -> Option<String> {
    if let Ok(python) = std::env::var("PYFUN_PYTHON")
        && !python.is_empty()
    {
        return Some(python);
    }
    for candidate in ["python", "python3"] {
        if Command::new(candidate)
            .arg("--version")
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .status()
