fn fmt_ce_block(s: &CeStmt, depth: usize) -> String {
    match s {
        CeStmt::For(p, src, body, _) if body.len() > 1 => {
            let mut out = format!("for {} in {}:", fmt_pat(p), fmt_expr(src));
