        if write_frame(&mut output, status)
            .and_then(|()| write_frame(&mut output, &reply.message))
            .and_then(|()| write_frame(&mut output, &reply.blob))
            .and_then(|()| output.flush())
            .is_err()
        {
            return ExitCode::SUCCESS;
        }
    }
}

