            edges: &Vec<Vec<usize>>,
            index: &mut usize,
            idx: &mut Vec<usize>,
            low: &mut Vec<usize>,
            on: &mut Vec<bool>,
            stack: &mut Vec<usize>,
            out: &mut HashMap<usize, Vec<usize>>,
