                    low[v] = low[v].min(low[w]);
                } else if on[w] {
                    low[v] = low[v].min(idx[w]);
                }
            }
            if low[v] == idx[v] {
                let mut comp = Vec::new();
                loop {
                    let w = stack.pop().unwrap();
                    on[w] = false;
                    comp.push(w);
                    if w == v {
                        break;
                    }
                }
                comp.sort();
                if comp.len() > 1 {
                    for &c in &comp {
                        out.insert(c, comp.clone());
                    }
                }
            }
        }
