    pub fn check_spawn(&mut self, acc: &EffAcc, at: Span) -> R<()> {
        let spawns = acc.labels.iter().any(|(l, _)| *l == Label::Spawn)
            || acc.tail.map_or(false, |(v, _)| self.st.eff(&Eff::var(v)).labels.contains(&Label::Spawn));
